#!/usr/bin/env python3
"""Copy the canonical detector spec (spec/entities.json) into each port.

python scripts/sync_spec.py           # write copies
python scripts/sync_spec.py --check   # exit 1 if any copy is stale (CI)
"""

from __future__ import annotations

import json
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
SPEC = ROOT / "spec" / "entities.json"

TARGETS = {
    ROOT / "packages/saaf-core/src/saaf/_data/entities.json": lambda raw: raw,
    ROOT / "packages/saaf-js/src/spec.generated.ts": lambda raw: (
        "// GENERATED by scripts/sync_spec.py from spec/entities.json. Do not edit.\n"
        'import type { RawSpec } from "./spec.js";\n\n'
        f"export const SPEC: RawSpec = {json.dumps(json.loads(raw), ensure_ascii=False, indent=2)};\n"
    ),
}


def main() -> int:
    raw = SPEC.read_text(encoding="utf-8")
    json.loads(raw)  # fail fast on invalid JSON
    check = "--check" in sys.argv
    stale = []
    for path, render in TARGETS.items():
        content = render(raw)
        current = path.read_text(encoding="utf-8") if path.exists() else None
        if current == content:
            continue
        if check:
            stale.append(path.relative_to(ROOT))
        else:
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(content, encoding="utf-8", newline="\n")
            print(f"wrote {path.relative_to(ROOT)}")
    if stale:
        print("stale spec copies (run `python scripts/sync_spec.py`):", *stale, sep="\n  ")
        return 1
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
